insert into public.modules (id, slug, title, summary, initially_unlocked, codex) values (1, 'edafologia', 'Edafología y Física de Suelos', 'Textura, estructura, agua del suelo, compactación, erosión y lectura de perfiles.', true, '[{"heading":"1.1 · Textura: la huella mineral","body":["La textura es la proporción de arena, limo y arcilla en la tierra fina (partículas menores a 2 mm). Según el USDA, la arena mide entre 2 y 0,05 mm, el limo entre 0,05 y 0,002 mm y la arcilla menos de 0,002 mm.","Con esos porcentajes se ubica el suelo en el triángulo textural, que define 12 clases (arenosa, franca, franco-arcillosa, arcillosa, etc.). La textura condiciona la retención de agua, la aireación, la CIC y la facilidad de laboreo.","A escala agronómica la textura no cambia con el manejo: es una propiedad heredada del material parental y de la meteorización. Por eso se maneja en torno a ella, no contra ella."]},{"heading":"1.1 · Cómo se mide: el método de Bouyoucos","body":["Se dispersa la muestra con hexametafosfato de sodio y agitación, para separar los agregados en partículas individuales, y se lleva a una probeta con agua.","Las partículas sedimentan según la Ley de Stokes: las más grandes caen más rápido. A los 40 segundos la arena ya decantó, así que el hidrómetro mide limo + arcilla en suspensión; a las 2 horas solo queda arcilla en suspensión.","El método de la pipeta es la referencia de laboratorio. En terreno, el \"tacto\" (formar una cinta con la muestra húmeda) permite una estimación rápida."]},{"heading":"1.1 · Estructura: la arquitectura del suelo","body":["La estructura es la forma en que las partículas se agrupan en agregados (peds). Los cementan arcillas, materia orgánica, óxidos de Fe y Al, el calcio (floculante) y la biología: raíces, hifas y la glomalina de los hongos micorrícicos.","Tipos principales: granular (típica de horizontes A con buena MO), bloques angulares y subangulares, prismática, columnar (asociada a suelos sódicos) y laminar (frecuente por compactación). Sin estructura: grano simple (arenas) o masiva.","El grado (débil, moderado, fuerte) indica qué tan definidos y estables son los agregados."]},{"heading":"1.1 · Estabilidad y manejo","body":["El sodio intercambiable (PSI alto) dispersa las arcillas: el suelo se sella, forma costras y estructura columnar. El calcio, por ejemplo aplicado como yeso, flocula y ayuda a recuperarlo.","La labranza excesiva y el tránsito con suelo húmedo destruyen agregados; la materia orgánica, las raíces vivas y los cultivos de cobertura los estabilizan.","La estabilidad de agregados se evalúa con tamizado en húmedo: más agregados estables significa mejor infiltración y menos erosión."]},{"heading":"1.2 · El agua retenida y el potencial mátrico","body":["El suelo retiene agua por adhesión a las superficies de las partículas y por capilaridad en los poros. Mientras más seco está, con más fuerza la retiene: esa fuerza se expresa como potencial mátrico (negativo), en kPa o bar.","Los poros grandes se vacían primero y a tensiones bajas; los poros finos (típicos de suelos arcillosos) retienen agua a tensiones muy altas."]},{"heading":"1.2 · Los puntos de referencia","body":["Saturación: todos los poros llenos de agua. Capacidad de Campo (CC): humedad tras drenar el exceso por gravedad, asociada a unos −33 kPa (−1/3 bar); en suelos arenosos se usa a menudo −10 kPa.","Punto de Marchitez Permanente (PMP): humedad a unos −1.500 kPa (−15 bar), donde la mayoría de los cultivos ya no recupera la turgencia.","Agua disponible (AD) = CC − PMP. Los suelos arcillosos tienen la CC y el PMP más altos; los francos y franco-limosos suelen tener la mayor agua disponible; los arenosos, la menor."]},{"heading":"1.2 · La curva característica de humedad","body":["La curva relaciona el contenido volumétrico de agua (θ) con el potencial mátrico. Se obtiene en laboratorio con ollas y placas de presión de Richards: muestras saturadas se someten a presiones conocidas (por ejemplo 0,33 y 15 bar) hasta equilibrar y se mide el agua retenida.","La curva presenta histéresis: a un mismo potencial, el suelo que se está secando retiene más agua que el que se está humedeciendo."]},{"heading":"1.2 · De la curva al riego","body":["Lámina de agua disponible: AD (mm) = (θCC − θPMP) × profundidad de raíces (mm). Ejemplo: θCC 30 %, θPMP 15 % y raíces a 600 mm dan 0,15 × 600 = 90 mm.","No se espera a llegar al PMP: se riega al alcanzar el agotamiento permisible, típicamente 30 a 50 % del AD según el cultivo. Con 50 % en el ejemplo, se reponen 45 mm.","Los tensiómetros miden en terreno entre 0 y unos −80 kPa: el rango útil para programar el riego de la mayoría de los frutales y hortalizas."]},{"heading":"1.3 · Densidad y porosidad","body":["La densidad aparente (Da) incluye los poros; la densidad real (Dr) considera solo los sólidos y en suelos minerales ronda 2,65 g/cm³. La porosidad total se estima como 1 − Da/Dr.","Valores típicos de Da: suelos arenosos 1,5–1,6 g/cm³; francos 1,3–1,4; arcillosos 1,1–1,3. Los Andisoles (trumaos) pueden bajar de 0,9 g/cm³.","Los macroporos drenan y airean; los microporos retienen agua. Un buen suelo agrícola combina ambos."]},{"heading":"1.3 · Aireación: las raíces también respiran","body":["Las raíces y la biota consumen O₂ y liberan CO₂; el intercambio ocurre por difusión a través de los poros con aire.","Se considera que bajo un 10 % de porosidad de aire (a capacidad de campo) aparece hipoxia: menor absorción de agua y nutrientes, más enfermedades de raíz y pérdidas de N por desnitrificación."]},{"heading":"1.3 · Compactación","body":["La compactación aumenta la Da, elimina macroporos y eleva la resistencia mecánica. Sus causas principales son el tránsito de maquinaria y el pisoteo, sobre todo con el suelo húmedo, cerca de capacidad de campo, cuando es más deformable.","El pie de arado es una capa compactada que se forma justo bajo la profundidad de labranza cuando se labra siempre a la misma profundidad.","Umbrales orientativos que restringen raíces: Da cercana a 1,6 g/cm³ en suelos francos, 1,45–1,5 en arcillosos y 1,75–1,8 en arenosos. Con penetrómetro de cono, sobre 2 MPa el crecimiento radicular se reduce fuertemente."]},{"heading":"1.3 · Recuperación","body":["Subsolar solo con el suelo friable o seco, para fracturar la capa en vez de amasarla; luego proteger el resultado con tránsito controlado (siempre por las mismas huellas).","Los cultivos de cobertura con raíz pivotante (como el rábano forrajero) funcionan como \"subsolado biológico\", y la materia orgánica mejora la resiliencia del suelo."]},{"heading":"1.4 · El proceso: desprender, transportar, depositar","body":["La erosión hídrica comienza con el impacto de la gota de lluvia, que desprende partículas (salpicadura) y sella la superficie. Luego el escurrimiento las transporta y las deposita aguas abajo.","Formas: laminar (pérdida pareja y poco visible), en surcos o regueros (canales pequeños que la labranza borra) y cárcavas (canales profundos que la labranza normal no puede cruzar ni borrar).","La erosión eólica mueve partículas por reptación, saltación y suspensión; es mayor en suelos secos, sueltos y sin cobertura."]},{"heading":"1.4 · Estimar la pérdida: la USLE","body":["La Ecuación Universal de Pérdida de Suelo estima la pérdida media anual: A = R · K · LS · C · P.","R es la erosividad de la lluvia; K, la erodabilidad del suelo (mayor en suelos limosos o de arenas muy finas con poca materia orgánica); LS, el largo y la inclinación de la pendiente; C, la cobertura y el manejo; P, las prácticas de conservación.","R, K y LS dependen del lugar; el agricultor actúa sobre C y P."]},{"heading":"1.4 · La erosión en Chile","body":["Según estudios de CIREN, cerca de la mitad del territorio nacional presenta algún grado de erosión, con situaciones críticas en el secano costero e interior de la zona central.","La combinación de lluvias concentradas en invierno, laderas sin cobertura y suelos degradados acelera la pérdida de la capa arable, que tarda siglos en formarse."]},{"heading":"1.4 · Prácticas de conservación","body":["Cobertura: cultivos de cobertura, mulch, rastrojos y cero labranza (bajan el factor C).","Prácticas mecánicas: cultivo en contorno, fajas, terrazas, zanjas de infiltración y control de cárcavas con diques (bajan el factor P).","Contra el viento: cortinas cortaviento y mantener el suelo cubierto."]},{"heading":"1.5 · La calicata","body":["Una calicata es un hoyo de observación de aproximadamente 1 × 1,5 m y 1,2 a 1,5 m de profundidad (o hasta la roca). Se describe la cara mejor iluminada, desde la superficie hacia abajo.","Se registran: límites y espesor de cada horizonte, color Munsell (matiz, valor y croma), textura al tacto, estructura, consistencia, raíces, poros, moteados, gravas y reacción al HCl (presencia de carbonatos)."]},{"heading":"1.5 · Horizontes maestros","body":["O: orgánico, de restos vegetales. A: mineral con materia orgánica acumulada, más oscuro. E: de eluviación, lavado de arcilla, hierro o MO, más claro. B: de acumulación o alteración (Bt arcilla iluvial, Bw cambio de color o estructura, Bk carbonatos, Bn sodio). C: material parental poco alterado. R: roca.","Los sufijos agregan detalle: p (alterado por arado, como en Ap), g (gleyzación por saturación de agua), t (arcilla iluvial), k (carbonatos), n (sodio)."]},{"heading":"1.5 · Factores formadores","body":["Jenny resumió la formación del suelo como función de cinco factores: clima, organismos, relieve, material parental y tiempo.","Los moteados grises y anaranjados indican saturación de agua y condiciones reductoras alternadas con oxidación: drenaje imperfecto. Son clave para decidir drenaje y especies."]},{"heading":"1.5 · Suelos de Chile","body":["Andisoles (trumaos) del centro-sur, formados de cenizas volcánicas: arcillas amorfas alofana e imogolita, baja Da, alta retención de agua, alta MO y fuerte fijación de fósforo.","Ñadis: andisoles hidromórficos con una capa cementada de fierrillo que impide el drenaje. Suelos rojos arcillosos (Alfisoles y Ultisoles) en el secano y la precordillera; Mollisoles en el valle central; Aridisoles y Entisoles en el norte."]}]'::jsonb)
