insert into public.modules (id, slug, title, summary, initially_unlocked, codex) values (7, 'cranberry', 'Cranberry', 'Acidófila de raíz superficial, heladas por aspersión y cosecha en agua.', true, '[{"heading":"Manejo Especializado de Cranberry","body":["Especie acidófila (pH 4,0-5,5) ineficiente absorbiendo nitratos (exige N amoniacal).","Posee tallos rastreros (runners) y verticales (uprights) donde fructifica en yemas apicales (ideal 400-600 uprights/pie²). Su sistema radicular superficial (10-15 cm) es muy susceptible a Phytophthora cinnamomi."]},{"heading":"Manejo térmico y cosecha","body":["Toleran hasta -18 °C en invierno profundo por deshidratación y antocianinas.","En primavera, se defienden de heladas con aspersión, aprovechando el calor latente de congelación (si el hielo se ve opaco y seco, la tasa de agua es insuficiente).","Cosecha en agua (water-harvest) para industria, donde las batidoras desprenden la fruta que flota por sus cámaras de aire."]}]'::jsonb)
insert into public.modules (id, slug, title, summary, initially_unlocked, codex) values (8, 'frambuesa', 'Frambuesa', 'Primocane vs floricane, camellones, conducción en V y pre-frío.', true, '[{"heading":"Manejo Avanzado de Frambuesa","body":["Arbusto de raíces perennes y cañas bianuales. Remontantes dan fruta en otoño (primocane) y no remontantes en verano (floricane, exige horas frío y muere postcosecha).","Su sensibilidad extrema a Phytophthora exige plantación en camellones."]},{"heading":"Conducción y postcosecha","body":["El manejo en \"V\" (T-trellis) abre la canopia y previene Botrytis. El raleo temprano de primocanes evita competencia con la floricane.","Tienen altísima tasa respiratoria postcosecha, requiriendo túneles de pre-frío (0 °C) en menos de 4 horas o atmósferas modificadas."]}]'::jsonb)
